    ('retail', '2026.10-prototype.1', 'IDENTITY_ASSESSMENT', 'CREATE_CONFIGURATION', 1, 'PROTOTYPE', 'PROTOTYPE_ASSUMPTION', 'New sellable identity under an existing product.', 'PROPOSED'),
    ('retail', '2026.10-prototype.1', 'IDENTITY_ASSESSMENT', 'USE_EXISTING', 2, 'PROTOTYPE', 'PROTOTYPE_ASSUMPTION', 'The requested sellable configuration already exists; its identity is returned rather than a second one created.', 'PROPOSED'),
    ('retail', '2026.10-prototype.1', 'IDENTITY_ASSESSMENT', 'NEW_VERSION', 3, 'PROTOTYPE', 'PROTOTYPE_ASSUMPTION', 'Existing identity, changed business state. No new configuration.', 'PROPOSED'),
