INSERT INTO ontology_authoring.configuration_dimensions
    (domain, ontology_version, dimension, ordinal, release_class, governance_basis, label, data_type, identity_affecting, proposed_identity_affecting, governance_state, blocks_identity_assessment, rationale, owner, authority, status)
VALUES
    ('retail', '2026.10-prototype.1', 'product_reference', 0, 'PROTOTYPE', 'PROTOTYPE_ASSUMPTION', 'Product reference', 'string', 'UNKNOWN', true, 'PROPOSED', true, 'PROTOTYPE ASSUMPTION. Prototype-only: 2026.10 has no counterpart. Q-007 asks whether any identifier spans the process, or identity starts at the material number.', NULL, NULL, 'proposed'),
    ('retail', '2026.10-prototype.1', 'geography', 1, 'PROTOTYPE', 'PROTOTYPE_ASSUMPTION', 'Geography', 'string', 'UNKNOWN', true, 'PROPOSED', true, 'PROTOTYPE ASSUMPTION. The prototype''s name for the 2026.10 ''geo'' dimension, which is UNKNOWN and unsigned there. 63 materials from geo additions, none replacing an existing material.', NULL, NULL, 'proposed'),
    ('retail', '2026.10-prototype.1', 'term_months', 2, 'PROTOTYPE', 'PROTOTYPE_ASSUMPTION', 'Contract term (months)', 'string', 'UNKNOWN', true, 'PROPOSED', true, 'PROTOTYPE ASSUMPTION. The prototype''s name for the 2026.10 ''term'' dimension, which is UNKNOWN and unsigned there. Q-009 asks whether term months and contract length months are the same business concept.', NULL, NULL, 'proposed'),
    ('retail', '2026.10-prototype.1', 'customer_segment', 3, 'PROTOTYPE', 'PROTOTYPE_ASSUMPTION', 'Customer segment', 'string', 'UNKNOWN', true, 'PROPOSED', true, 'PROTOTYPE ASSUMPTION. The prototype''s name for the 2026.10 ''segment'' dimension, which is UNKNOWN and unsigned there.', NULL, NULL, 'proposed'),
    ('retail', '2026.10-prototype.1', 'user_tier', 4, 'PROTOTYPE', 'PROTOTYPE_ASSUMPTION', 'User tier', 'string', 'UNKNOWN', false, 'PROPOSED', true, 'PROTOTYPE ASSUMPTION -- THE MOST CONSEQUENTIAL ONE IN THIS RELEASE. Assumed NOT identity-bearing, which is what makes IR-005 conclude NEW_VERSION and what avoids 78 of the 92 replacement materials in the corpus. If Claris says user tier IS identity-bearing, IR-005 becomes CREATE_CONFIGURATION and that saving does not exist. Unvalidated.', NULL, NULL, 'proposed'),
    ('retail', '2026.10-prototype.1', 'package_format', 5, 'PROTOTYPE', 'PROTOTYPE_ASSUMPTION', 'Package format', 'string', 'UNKNOWN', false, 'PROPOSED', true, 'PROTOTYPE ASSUMPTION WITH A RECORDED CONFLICT. 2026.10 proposes this dimension IS identity-bearing (IR-006 -> CREATE_CONFIGURATION), but the locked prototype identity tuple excludes it, so this release assumes NOT identity-bearing in order to keep the tuple at four properties. The two assumptions disagree: under this release a repackage yields an identical canonical identity and the exact-match predicate concludes NO_BUSINESS_CHANGE, so the CREATE_CONFIGURATION that IR-006 proposes is unreachable. Recorded, not resolved: resolving it means changing tuple membership, which G.5P locked.', NULL, NULL, 'proposed'),
    ('retail', '2026.10-prototype.1', 'description', 6, 'PROTOTYPE', 'PROTOTYPE_ASSUMPTION', 'Description', 'string', 'UNKNOWN', false, 'PROPOSED', true, 'PROTOTYPE ASSUMPTION. Assumed not identity-bearing, matching 2026.10''s own proposal. 2026.10 marks it CONFIRMED but with no confirmed_by or confirmed_on, so it is unsigned there and unconfirmed here.', NULL, NULL, 'proposed');
INSERT INTO ontology_authoring.identity_rules
    (domain, ontology_version, rule, ordinal, release_class, governance_basis, change_type, reads_dimension, proposed_effect, identity_effect, governance_state, rationale, blocking_note, owner, authority, status)
VALUES
    ('retail', '2026.10-prototype.1', 'IR-001', 0, 'PROTOTYPE', 'PROTOTYPE_ASSUMPTION', 'new_product_family', NULL, 'CREATE_PRODUCT', NULL, 'PROPOSED', 'Tautological in the source: a new family is a new commercial product by definition. Reads no dimension.', NULL, NULL, NULL, 'proposed'),
    ('retail', '2026.10-prototype.1', 'IR-002', 1, 'PROTOTYPE', 'PROTOTYPE_ASSUMPTION', 'geo_add', 'geography', 'CREATE_CONFIGURATION', NULL, 'PROPOSED', '63 materials in the corpus came from geo additions and none replaced an existing material.', NULL, NULL, NULL, 'proposed'),
    ('retail', '2026.10-prototype.1', 'IR-003', 2, 'PROTOTYPE', 'PROTOTYPE_ASSUMPTION', 'term_add', 'term_months', 'CREATE_CONFIGURATION', NULL, 'PROPOSED', '33 materials, none replacing an existing one.', NULL, NULL, NULL, 'proposed'),
    ('retail', '2026.10-prototype.1', 'IR-004', 3, 'PROTOTYPE', 'PROTOTYPE_ASSUMPTION', 'segment_add', 'customer_segment', 'CREATE_CONFIGURATION', NULL, 'PROPOSED', '19 materials, none replacing an existing one.', NULL, NULL, NULL, 'proposed'),
    ('retail', '2026.10-prototype.1', 'IR-005', 4, 'PROTOTYPE', 'PROTOTYPE_ASSUMPTION', 'tier_restructure', 'user_tier', 'NEW_VERSION', NULL, 'PROPOSED', '78 of the 92 materials that replaced an existing material came from tier restructures. This assumption is what turns them into versions.', 'PROMINENT LABEL REQUIRED. This is the single most consequential assumption in the release and the one most expensive to get wrong. Any figure derived from it must be shown alongside the fact that it is unvalidated.', NULL, NULL, 'proposed'),
    ('retail', '2026.10-prototype.1', 'IR-006', 5, 'PROTOTYPE', 'PROTOTYPE_ASSUMPTION', 'repackage', 'package_format', NULL, NULL, 'UNPROPOSED', '12 materials from repackaging, all replacing an existing one.', 'NOT EXECUTABLE IN THIS PROTOTYPE (D.4G.2 section 1). 2026.10 proposes repackage -> CREATE_CONFIGURATION, but package_format is not one of the four locked identity properties, so the two assumptions cannot both execute coherently. The rule is retained for provenance with proposed_effect NULL and status undefined, so no executable derivation can reach it. A repackage must conclude CANNOT_DECIDE / IDENTITY_POLICY_NOT_DEFINED, exactly as reclassify/SLP does. Resolving it means changing tuple membership, which G.5P locked.', NULL, NULL, 'undefined'),
    ('retail', '2026.10-prototype.1', 'IR-008', 6, 'PROTOTYPE', 'PROTOTYPE_ASSUMPTION', 'price_change', NULL, 'NEW_VERSION', NULL, 'PROPOSED', 'Verified against the corpus: three price changes minted nothing. Reads no dimension.', NULL, NULL, NULL, 'proposed'),
    ('retail', '2026.10-prototype.1', 'IR-009', 7, 'PROTOTYPE', 'PROTOTYPE_ASSUMPTION', 'rename', 'description', 'NO_BUSINESS_CHANGE', NULL, 'PROPOSED', 'Verified against the corpus: two renames minted nothing.', NULL, NULL, NULL, 'proposed');
